def _line(row: List[str], widths: List[int]) -> str:
    pairs = zip(row, widths)
    return "  ".join(
        cell.ljust(wide) for cell, wide in pairs
    ).rstrip()


def _align(table: List[List[str]]) -> List[str]:
    widths = [max(map(len, col)) for col in zip(*table)]
    return [_line(row, widths) for row in table]


